    "",
    "NODE_ENV=development",
    "PORT=3000",
    "TRUST_PROXY=1",
    "",
    f"DATABASE_URL={env_vars.get('DATABASE_URL', '')}",
    f"JWT_SECRET={secrets.get('JWT_SECRET', '')}",
    "",
    f"SUPABASE_URL={SUPABASE_URL}",
    f"SUPABASE_PUBLISHABLE_KEY={SUPABASE_PUBLISHABLE_KEY}",
    f'SUPABASE_JWT_SECRET="{SUPABASE_JWT_SECRET}"',
    "",
    "# Exposed to the browser at build time (public by design).",
    f"VITE_SUPABASE_URL={SUPABASE_URL}",
    f"VITE_SUPABASE_PUBLISHABLE_KEY={SUPABASE_PUBLISHABLE_KEY}",
