# Never echo the values back - just confirm the shape.
keys = [l.split("=", 1)[0] for l in lines if "=" in l and not l.startswith("#")]
print(f"wrote {target} ({len(keys)} keys, mode 0600)")
empty = [k for k in keys if not dict(
    (l.split("=", 1)[0], l.split("=", 1)[1].strip('"')) for l in lines if "=" in l and not l.startswith("#")
)[k]]
print("empty:", empty if empty else "none")
